import{_ as a,c as e,j as i,t,a5 as l,o}from"./chunks/framework.BLFC1wTn.js";const r="/weichatPay.png",g=JSON.parse('{"title":"小程序","description":"","frontmatter":{},"headers":[],"relativePath":"pages/interview/weichat/index.md","filePath":"pages/interview/weichat/index.md","lastUpdated":null}'),n={name:"pages/interview/weichat/index.md"},h=l('<h1 id="小程序" tabindex="-1">小程序 <a class="header-anchor" href="#小程序" aria-label="Permalink to &quot;小程序&quot;">​</a></h1><h2 id="微信小程序" tabindex="-1">微信小程序 <a class="header-anchor" href="#微信小程序" aria-label="Permalink to &quot;微信小程序&quot;">​</a></h2><p>小程序本质就是一个SPA单页面应用，所有的页面渲染和事件处理都在一个页面内进行，它的架构模式，是数据驱动模式，它的UI和数据是分离的，页面的更新都要数据驱动。技术和前端开发差不多，采用js、wxml、wxss。功能可分为webView、appService两部分，在两个进程中进行，通过系统层的JSBridge进行通信。</p><ol><li>webView，用来展示UI，</li><li>appService，用来处理逻辑和数据，包括数据请求、数据存储、事件处理等。</li></ol><h2 id="小程序的主要目录和文件" tabindex="-1">小程序的主要目录和文件 <a class="header-anchor" href="#小程序的主要目录和文件" aria-label="Permalink to &quot;小程序的主要目录和文件&quot;">​</a></h2><ol><li>project.config.json：小程序的配置文件，包括appid、appname、version，开启https校验等信息</li><li>App.js，设置一些全局的基础数据</li><li>App.json，底部tab，标题栏和路由设置</li><li>App.wxss,公共样式，引入iconfont等</li><li>pages，具体页面</li><li>index.json，配置当前页面标题和引入组件</li><li>index.wxml,页面结构</li><li>index.wxss，页面样式</li><li>index.js，页面的逻辑，请求和数据处理</li></ol><h2 id="wxml和html的异同" tabindex="-1">wxml和html的异同 <a class="header-anchor" href="#wxml和html的异同" aria-label="Permalink to &quot;wxml和html的异同&quot;">​</a></h2>',7),s=i("li",null,"相同点：都是用来描述页面结构的语言",-1),d=i("li",null,"都有标签和属性构成",-1),p=i("li",null,"组件封装不同，wxml对组件进行了重新封装",-1),c=i("li",null,"小程序运行在JS Core内，没有DOM和Window对象",-1),u=l('<h2 id="封装微信小程序的数据请求" tabindex="-1">封装微信小程序的数据请求 <a class="header-anchor" href="#封装微信小程序的数据请求" aria-label="Permalink to &quot;封装微信小程序的数据请求&quot;">​</a></h2><ol><li>在根目录下创建utils目录及api.js文件和apiConfig.js文件</li><li>在apiConfig.js文件中配置请求的url和请求方法、请求头、带上token和异常处理</li><li>在api.js文件中引入apiConfig.js文件，根据页面数据请求url，设置对应方法并导出</li><li>在具体的页面中引入接口并在统一的文件中导出</li><li>在app.js中创建封装请求数据的方法</li><li>在子页面中调用封装的请求数据</li></ol><h2 id="小程序传递数据" tabindex="-1">小程序传递数据 <a class="header-anchor" href="#小程序传递数据" aria-label="Permalink to &quot;小程序传递数据&quot;">​</a></h2><ol><li>页面跳转或重定向时，使用url带参数传递数据</li><li>使用组件模块template传递参数</li><li>使用缓存传递参数</li><li>给wxml元素添加data-xxx传递，通过e.currentTarget.dataset.xxx获取</li><li>设置id标识传递，通过e.currentTarget.id获取</li><li>在navigateTo或redirectTo中传递参数</li></ol><h2 id="小程序的双向绑定" tabindex="-1">小程序的双向绑定 <a class="header-anchor" href="#小程序的双向绑定" aria-label="Permalink to &quot;小程序的双向绑定&quot;">​</a></h2><p>小程序之间的this.data的属性不能同步到视图，必须要调用this.setData方法来更新视图。</p><h2 id="小程序的主要生命周期函数" tabindex="-1">小程序的主要生命周期函数 <a class="header-anchor" href="#小程序的主要生命周期函数" aria-label="Permalink to &quot;小程序的主要生命周期函数&quot;">​</a></h2><ol><li>onLoad，页面加载时触发，只执行一次，可获取当前页面路径中的参数</li><li>onShow，页面显示/切入前台时触发，一般用来发送数据</li><li>onReady，页面初次渲染时触发，只执行一次，页面已经可以和视图层交互</li><li>onHide，页面隐藏/切入后台时触发</li><li>onUnload，页面卸载时触发，如redictTo或navigateBack，一般用来销毁定时器、解绑事件监听等</li></ol><h2 id="原生小程序、wepy、mpvue" tabindex="-1">原生小程序、wepy、mpvue <a class="header-anchor" href="#原生小程序、wepy、mpvue" aria-label="Permalink to &quot;原生小程序、wepy、mpvue&quot;">​</a></h2><ol><li>原生小程序，使用原生的JS、WXML、WXSS，可以直接调用微信提供的API，缺乏组件化，但坑少，适合原生开发者</li><li>Wepy，Wepy 是一个基于 Vue.js 的小程序开发框架，旨在以更现代化的方式编写小程序。使用 Vue 的组件化开发模式，支持 ES6/7 语法和一些现代前端工具特性。开发者可以使用 Vue 的指令和生命周期函数等。但是，Wepy 的社区和生态相对较小。</li><li>mpvue 是一个由美团点评开源的框架，也是基于 Vue.js 的小程序开发解决方案。拥有较大的社区支持和生态，可以使用 Vue 的各种插件和库</li></ol><h2 id="提高小程序应用速度" tabindex="-1">提高小程序应用速度 <a class="header-anchor" href="#提高小程序应用速度" aria-label="Permalink to &quot;提高小程序应用速度&quot;">​</a></h2><ol><li>提高页面的加载速度，使用压缩图片、压缩代码、减少请求等方式</li><li>用户行为预测，使用用户行为数据进行页面优化，比如用户停留时间、点击行为、浏览路径等</li><li>减少默认data大小</li><li>组件化，使用组件来提高代码复用性和可维护性</li></ol><h2 id="小程序的优劣" tabindex="-1">小程序的优劣 <a class="header-anchor" href="#小程序的优劣" aria-label="Permalink to &quot;小程序的优劣&quot;">​</a></h2><ol><li><p>容易上手、基础组件完善，开发文档完善，社区活跃，基本不考虑兼容问题</p></li><li><p>良好的用户体验，不需要下载，速度快，也可以添加到桌面</p></li><li><p>开发成本比APP低</p></li><li><p>严格的审查流程，有利于提升产品质量</p></li><li><p>限制较多，页面大小不能超多1M，不能打开超过5个层级的页面</p></li><li><p>样式单一，部分组件样式成型，不支持自定义样式</p></li><li><p>推广面窄，不适合大众推广</p></li><li><p>依托于微信，无法开发后台管理功能</p></li><li><p>后台调试麻烦，api接口必须要https且公网地址</p></li><li><p>真机测试，个别安卓和苹果表现迥异</p></li></ol><h2 id="小程序关联微信公众号如何确定用户唯一性" tabindex="-1">小程序关联微信公众号如何确定用户唯一性 <a class="header-anchor" href="#小程序关联微信公众号如何确定用户唯一性" aria-label="Permalink to &quot;小程序关联微信公众号如何确定用户唯一性&quot;">​</a></h2><p>我是用wx.getUserInfo获取用户信息，withCredentials为true，可以获取encryptedData,里面有unionId，可以用来确定用户唯一性。</p><h2 id="小程序调用后台接口问题" tabindex="-1">小程序调用后台接口问题 <a class="header-anchor" href="#小程序调用后台接口问题" aria-label="Permalink to &quot;小程序调用后台接口问题&quot;">​</a></h2><ol><li>数据大小限制，超过范围会直接导致小程序崩溃；</li><li>小程序不可以直接渲染文章内容这类html文本，需要借助插件</li></ol><h2 id="小程序下拉刷新" tabindex="-1">小程序下拉刷新 <a class="header-anchor" href="#小程序下拉刷新" aria-label="Permalink to &quot;小程序下拉刷新&quot;">​</a></h2><p>使用view代替scroll-view，并设置refresher属性，触发下拉刷新事件，在onPullDownRefresh中处理刷新逻辑。</p><h2 id="bindtap和catchtap的区别" tabindex="-1">bindtap和catchtap的区别 <a class="header-anchor" href="#bindtap和catchtap的区别" aria-label="Permalink to &quot;bindtap和catchtap的区别&quot;">​</a></h2><p>bind事件绑定不会阻止冒泡事件向上冒泡，catch事件绑定可以阻止冒泡事件向上冒泡。</p><h2 id="小程序路由" tabindex="-1">小程序路由 <a class="header-anchor" href="#小程序路由" aria-label="Permalink to &quot;小程序路由&quot;">​</a></h2><ol><li>wx.navigateTo()：保留当前页面，跳转到应用内的某个页面，不能跳转到tabbar页面；</li><li>wx.redirectTo()：关闭当前页面，跳转到应用内的某个页面，不能跳转到tabbar页面；</li><li>wx.switchTab()：跳转到应用内的某个tabbar页面，并关闭其他所有非tabbar页面；</li><li>wx.navigateBack()：关闭当前页面，返回上一页面或多级页面。可通过getCurrentPages()获取当前的页面栈，决定返回几层。</li><li>wx.reLaunch()：关闭当前页面，重新打开应用，并跳转到应用内的某个页面。</li></ol><h2 id="小程序和vue写法的区别" tabindex="-1">小程序和Vue写法的区别 <a class="header-anchor" href="#小程序和vue写法的区别" aria-label="Permalink to &quot;小程序和Vue写法的区别&quot;">​</a></h2><ol><li>遍历的时候，小程序是wx:for=&quot;list&quot;，Vue是v-for=&quot;item in list&quot;；</li><li>调用data赋值的时候： <ol><li>小程序是this.data.name，Vue是this.name；</li><li>赋值是this.setData({name: &#39;value&#39;})，Vue是this.name = value。</li></ol></li></ol><h2 id="小程序与原生app" tabindex="-1">小程序与原生APP <a class="header-anchor" href="#小程序与原生app" aria-label="Permalink to &quot;小程序与原生APP&quot;">​</a></h2><p>小程序：<br> 优点：</p><ol><li>基于微信平台开发，有微信buff</li><li>无需安装，只要打开微信就能用，不占手机内存，体验好</li><li>开发周期短</li><li>成本较少</li><li>小程序名称唯一，在搜索里面权重高</li><li>容易上手，学过前端基本没有太大问题</li><li>基本不考虑兼容性</li><li>发布、审核、上线流程简单</li><li>开发文档活跃、社区活跃</li><li>支持插件式开发，一些基本功能可以开发成插件供多个程序使用</li></ol><p>原生APP：</p><ol><li>原生的响应速度快</li><li>对于有无网络操作时，基本选用原生</li><li>需要调用系统硬件的功能</li><li>在无网络或者弱网情况下体验好</li><li>开发周期长，成本高，需要下载</li></ol><h2 id="小程序的发布流程" tabindex="-1">小程序的发布流程 <a class="header-anchor" href="#小程序的发布流程" aria-label="Permalink to &quot;小程序的发布流程&quot;">​</a></h2><ol><li>注册微信小程序账号</li><li>获取微信小程序的APPID</li><li>下载微信开发者工具，注册开发者账号</li><li>创建demo项目</li><li>去微信公众号配置域名</li><li>手机浏览</li><li>代码上传</li><li>提交审核</li><li>发布上线</li></ol><h2 id="小程序常见问题" tabindex="-1">小程序常见问题 <a class="header-anchor" href="#小程序常见问题" aria-label="Permalink to &quot;小程序常见问题&quot;">​</a></h2><ol><li>rpx：使用rpx可以使小程序的UI适配不同屏幕大小</li><li>wx.navigateTo()无法打开页面，一个应用只能同时打开5个页面，避免多层级交互，使用redirectTo</li><li>tabBar不显示： <ol><li>tabBar的数量少于2项或超过5项</li><li>tabBar写法错误</li><li>tabBar没有写pagePath字段</li></ol></li></ol><h2 id="微信实现支付功能" tabindex="-1">微信实现支付功能 <a class="header-anchor" href="#微信实现支付功能" aria-label="Permalink to &quot;微信实现支付功能&quot;">​</a></h2><p>实现微信支付的三种方式：</p><ol><li>云调用，使用云函数免密调用微信支付接口，开发者无需关心证书、签名、微信支付服务器端文档，使用简单，代码较少，只需要调用相应的函数即可</li><li>使用云开发工作流进行逻辑编排，通过连接器调用微信支付接口，相比云调用支持更加复杂、通用的业务场景</li><li>云开发管理系统内置了「微信支付管理」模板，支持 Web 端登录使用，提供订单查询、退款等功能，开发者也可对模板进行自定义修改</li></ol><p><a href="https://developers.weixin.qq.com/miniprogram/dev/wxcloud/guide/wechatpay/wechatpay.html#%E5%BE%AE%E4%BF%A1%E6%94%AF%E4%BB%98" target="_blank" rel="noreferrer">微信支付官方文档</a></p><p>使用工作流对接微信支付： <img src="'+r+'" alt="支付"></p>',40);function b(m,x,_,q,w,f){return o(),e("div",null,[h,i("ol",null,[s,d,i("li",null,"多了wx:if这样的属性和"+t()+"表达式等",1),p,c]),u])}const k=a(n,[["render",b]]);export{g as __pageData,k as default};
